window.docContents[210].resolve({"/2___-Basic-notions-of-representation-theory/2___3___-Representations/Schur___s-lemma/#Chapter2___Proposition2___3___9":{"contents":"Proposition 2.3.9 (Schur's lemma). Let V_1, V_2 be representations of an algebra A over any field F (which need not be algebraically closed). Let \\phi : V_1 \\to V_2 be a nonzero homomorphism of representations. Then:\n\n(i) If V_1 is irreducible, \\phi is injective.\n\n(ii) If V_2 is irreducible, \\phi is surjective.\n\nThus, if both V_1 and V_2 are irreducible, \\phi is an isomorphism.\n\nProof. (i) The kernel K of \\phi is a subrepresentation of V_1. Since \\phi \\neq 0, this subrepresentation cannot be V_1. So by irreducibility of V_1 we have K = 0.\n\n(ii) The image I of \\phi is a subrepresentation of V_2. Since \\phi \\neq 0, this subrepresentation cannot be 0. So by irreducibility of V_2 we have I = V_2. \\square\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.3. Representations\tSchur's lemma","header":"Schur's lemma","id":"/2___-Basic-notions-of-representation-theory/2___3___-Representations/Schur___s-lemma/#Chapter2___Proposition2___3___9"},"/5___-Representations-of-finite-groups___-Further-results/5___19___-Schur-Weyl-duality-for-___GL_LPAR_V_RPAR____/Section-5___19___-Schur-Weyl-duality-for-GL_LPAR_V_RPAR_/#Chapter5___Introduction_5___19":{"contents":"\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.19. Schur-Weyl duality for $GL(V)$\tSection 5.19: Schur-Weyl duality for GL(V)","header":"Section 5.19: Schur-Weyl duality for GL(V)","id":"/5___-Representations-of-finite-groups___-Further-results/5___19___-Schur-Weyl-duality-for-___GL_LPAR_V_RPAR____/Section-5___19___-Schur-Weyl-duality-for-GL_LPAR_V_RPAR_/#Chapter5___Introduction_5___19"}});
